import{_ as n,l as r,o as e,c as s,v as t,p as i,x as o,d,i as p,S as h}from"./chunks/framework.InCnrqk-.js";const S=JSON.parse('{"title":"最近点对","description":"","frontmatter":{"title":"最近点对","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/closest-pair.md","filePath":"cs/closest-pair.md","lastUpdated":1789023840000}'),c={name:"cs/closest-pair.md"};function _(m,a,u,f,B,T){const l=r("Mermaid");return e(),s("div",null,[a[1]||(a[1]=t('<h1 id="最近点对" tabindex="-1">最近点对 <a class="header-anchor" href="#最近点对" aria-label="Permalink to &quot;最近点对&quot;">​</a></h1><div class="epigraph"><p>平面最近点对可分治：$O(n\\log n)$ 排序后，中线带宽内最多常数个候选，总 $T(n)=2T(n/2)+O(n)$。</p><footer>—— 据 Shamos and Hoey, Closest-Point Problems, 1975；CLRS 第 33.4 节整理</footer></div><p>上一课<a href="/cs/sweep-line">扫描线</a>处理覆盖。最近点对：\\(\\min_{i\\neq j}\\|p_i-p_j\\|\\)。朴素 \\(O(n^2)\\)。缺口是分治：按 \\(x\\) 中位数切开，带宽 \\(\\delta\\) 内按 \\(y\\) 扫。不重写卡壳直径（那是最远）。后课线段相交。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>左右各递归得 \\(\\delta\\)。中线 \\(x\\) 附近宽度 \\(2\\delta\\) 的点按 \\(y\\) 排序（可归并）。每个点只与其后常数个（网格论证至多 7）比较。\\(O(n\\log n)\\)。</p><p>扫描线：平衡树按 \\(y\\) 维护距左 \\(\\delta\\) 的点，同样 \\(O(n\\log n)\\)。</p><p>缺口是带宽常数候选，不是旋转卡壳。</p><h3 id="最远点对不是本课" tabindex="-1">最远点对不是本课 <a class="header-anchor" href="#最远点对不是本课" aria-label="Permalink to &quot;最远点对不是本课&quot;">​</a></h3><p>最远在凸包直径。最近点通常在内部。不要混。</p><p><span class="marginnote">Shamos–Hoey 1975。CLRS 33.4。后课 BO 线段交。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>预排序 \\(x\\)。分治归并 \\(y\\)。或扫描 + 树。注意重合点距离 0。</p>',12)),(e(),i(h,null,{default:o(()=>[p(l,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20X%5B%22%E6%8C%89%20x%20%E5%88%86%E6%B2%BB%22%5D%20--%3E%20D%5B%22%E5%B7%A6%E5%8F%B3%20%CE%B4%22%5D%0A%20%20D%20--%3E%20STR%5B%22%E4%B8%AD%E5%B8%A6%E6%8C%89%20y%22%5D%0A%20%20STR%20--%3E%20NN%5B%22%E6%9C%80%E8%BF%91%E7%82%B9%22%5D%0A"})]),fallback:o(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>三维类似但带宽候选不再常数级同样简单。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>鸽笼：\\(\\delta\\times\\delta\\) 方格里至多一点来自一侧最优，故沿 \\(y\\) 常数邻居。与主定理：\\(O(n\\log n)\\)。与哈希网格期望线性点名。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写高维最近点的 \\(n^{1+\\varepsilon}\\)。动态最近点不写。后课默认：平面最近点对 \\(O(n\\log n)\\)。下一课 Bentley–Ottmann。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>分治中带常数比较。</li><li>\\(O(n\\log n)\\)；最远走凸包。</li><li>扫描线变体同类。</li><li>出处：Shamos and Hoey, 1975；CLRS 第 33.4 节。</li></ul>',7))])}const x=n(c,[["render",_]]);export{S as __pageData,x as default};
